contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bool fundFirst) public payable {
        // Optionally fund c so it has a nonzero starting balance.
        if (fundFirst) {
            require(address(this).balance >= 1 ether);
            address(c).call{value: 1 ether}("");
        }
        uint before = address(c).balance;
        require(address(this).balance >= amount);
        // Recipient is this contract, which accepts Ether via receive().
        bool reverted;
        try c.multiplicate{value: amount}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted && ((amount >= before) ? address(c).balance == 0 : address(c).balance == before));
    }
    receive() external payable {}
    fallback() external payable {}
}

