    function run(uint amount1, uint amount2) public payable {
        require(address(this).balance >= amount1 + amount2);
        // Setup: with balance 0, multiplicate to c itself sends balance+msg.value to c,
        // so c ends up holding exactly amount1.
        c.multiplicate(address(c));
        uint balC = address(c).balance;
        require(balC == amount1);
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.multiplicate{value: amount2}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (amount2 >= amount1) {
            assert(!reverted && address(c).balance == 0 && address(this).balance == beforeThis + amount2);
        } else {
            assert(reverted && address(c).balance == amount1 && address(this).balance == beforeThis - amount1);
        }
    }
    receive() external payable {}
    fallback() external payable {}
}

